<template>
  <div class="ask-actions" :class="`ask-actions-${surface}`">
    <div v-if="entryActions.length" class="ask-actions-row">
      <button
        v-for="entry in entryActions"
        :key="entry.key"
        type="button"
        class="ask-action"
        :data-ask-navigate="entry.navigate ? '1' : undefined"
        @click="run(entry)"
      >
        <span>{{ entry.label }}</span><ArrowUpRightIcon />
      </button>
    </div>
    <div v-if="labVisible" class="ask-actions-lab" data-ask-actions-lab>
      <p class="ask-actions-lab-kicker">Try the live comparison</p>
      <RetrievalLab />
    </div>
  </div>
</template>

<script>
import ArrowUpRightIcon from './ArrowUpRightIcon.vue';
import RetrievalLab from '../view/RetrievalLab.vue';

const ACTION_COPY = {
  search: 'Search the site',
  ask: 'Ask a question',
  view: 'Compose a View',
  views: 'Explore public Views',
};

export default {
  name: 'AskActions',
  components: { ArrowUpRightIcon, RetrievalLab },
  props: {
    actions: {
      type: Array,
      default: () => [],
    },
    surface: {
      type: String,
      default: 'home',
    },
  },
  computed: {
    entryActions() {
      return (this.actions || [])
        .filter((entry) => entry.type !== 'component')
        .map((entry, index) => ({
          ...entry,
          key: `${entry.type}-${entry.action || entry.path || entry.id || index}`,
          label: entry.type === 'action' ? ACTION_COPY[entry.action] : entry.label,
          navigate: entry.type === 'link' || (entry.type === 'action' && entry.action === 'views'),
        }))
        .filter((entry) => entry.label);
    },
    labVisible() {
      return (this.actions || []).some((entry) => entry.type === 'component' && entry.id === 'retrieval-lab');
    },
  },
  methods: {
    run(entry) {
      if (entry.type === 'action') {
        const eventName = {
          search: 'open-site-search',
          ask: 'open-site-ask',
          view: 'open-site-view',
        }[entry.action];
        if (eventName) window.dispatchEvent(new CustomEvent(eventName));
        else if (entry.action === 'views') this.$router.push('/views').catch(() => {});
        return;
      }
      if (entry.type === 'link' && entry.path) {
        this.$router.push(entry.path).catch(() => {});
      }
    },
  },
};
</script>

